import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ name, userName, userUsername, username, grade, subjects, handleLogout }) {
  const [materials, setMaterials] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // 🟢 NEW STATE: දැනට සිසුවා තෝරාගෙන සිටින සක්‍රීය විෂය (Mathematics / ICT) මතක තබා ගැනීමට
  const [selectedSubjectFilter, setSelectedSubjectFilter] = useState('');

  // දැනට බලන PDF/Video නිබන්ධනය තබා ගන්නා ප්‍රදර්ශක State එක
  const [previewMaterial, setPreviewMaterial] = useState(null);

  // සැබෑ ලොගින් දත්ත හඳුනාගැනීම (Props Fallbacks)
  const loggedInUsername = username || userUsername || '';
  const loggedInName = name || userName || '';

  // ඩේටාබේස් එකෙන් කෙලින්ම ඇදගන්නා ශිෂ්‍ය තොරතුරු State එක
  const [liveProfile, setLiveProfile] = useState(null);

  // 🔒 PASSWORD CHANGE STATES
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  useEffect(() => {
    // ඩේටාබේස් එකේ Enrolled වෙලා තියෙන ඇත්තම සබ්ජෙක්ට්ස් ටික ලයිව්ම කියවීම
    axios.get('http://localhost:8082/api/view-students')
      .then(res => {
        if (Array.isArray(res.data)) {
          const currentStudent = res.data.find(s => 
            (s.username && loggedInUsername && String(s.username).toLowerCase() === String(loggedInUsername).toLowerCase()) ||
            (s.name && loggedInName && String(s.name).toLowerCase() === String(loggedInName).toLowerCase())
          );
          if (currentStudent) {
            setLiveProfile(currentStudent);
          }
        }
      })
      .catch(err => console.error("Profile Live Sync Error:", err));
  }, [loggedInUsername, loggedInName]);

  const displayNameStr = liveProfile ? liveProfile.name : (loggedInName || 'Student');
  const displayGradeStr = liveProfile ? liveProfile.grade : (grade || 'Grade 8');
  const displaySubjectsStr = liveProfile ? liveProfile.subjects : (subjects || '');
  
  const mySubjects = displaySubjectsStr ? displaySubjectsStr.split(', ') : [];

  useEffect(() => {
    if (!displayGradeStr) return;

    // 1. නිබන්ධන කියවීම සහ ෆිල්ටර් කිරීම
    axios.get('http://localhost:8082/api/learning-materials')
      .then(res => {
        const allMaterials = Array.isArray(res.data) ? res.data : [];
        const filtered = allMaterials.filter(m => 
          String(m.grade).toLowerCase() === String(displayGradeStr).toLowerCase() &&
          mySubjects.some(sub => m.subject && m.subject.toLowerCase() === sub.toLowerCase())
        );
        setMaterials(filtered);
      })
      .catch(err => console.error("Materials Fetch Error:", err));

    // 2. ප්‍රශ්න පත්‍ර කියවීම සහ ෆිල්ටර් කිරීම
    axios.get('http://localhost:8082/api/quizzes')
      .then(res => {
        const allQuizzes = Array.isArray(res.data) ? res.data : [];
        const filtered = allQuizzes.filter(q => 
          String(q.grade).toLowerCase() === String(displayGradeStr).toLowerCase() &&
          (q.is_enabled === 1 || q.is_enabled === true) &&
          mySubjects.some(sub => q.subject_name && q.subject_name.toLowerCase() === sub.toLowerCase())
        );
        setQuizzes(filtered);
      })
      .catch(err => console.error("Quizzes Fetch Error:", err));
  }, [displayGradeStr, displaySubjectsStr]);

  // 🟢 DYNAMIC LIVE FILTER LOGIC: තෝරාගත් විෂය අනුව පමණක් ලයිව් පෙරා පෙන්වීම
  const displayedMaterials = selectedSubjectFilter
    ? materials.filter(m => m.subject && m.subject.toLowerCase() === selectedSubjectFilter.toLowerCase())
    : materials;

  const displayedQuizzes = selectedSubjectFilter
    ? quizzes.filter(q => q.subject_name && q.subject_name.toLowerCase() === selectedSubjectFilter.toLowerCase())
    : quizzes;

  // 🔑 PASSWORD SUBMIT HANDLER
  const handlePasswordChange = (e) => {
    e.preventDefault();
    if (!currentPassword || !newPassword || !confirmPassword) {
      alert("⚠️ කරුණාකර සියලුම හිස්තැන් පුරවන්න.");
      return;
    }
    if (newPassword !== confirmPassword) {
      alert("⚠️ නව රහස්පදය සහ එය තහවුරු කිරීමේ රහස්පදය නොගැලපේ.");
      return;
    }

    // Backend API එකට දත්ත යැවීම
    axios.post('http://localhost:8082/api/change-password', {
      username: loggedInUsername,
      currentPassword: currentPassword,
      newPassword: newPassword
    })
    .then(res => {
      alert("✅ රහස්පදය සාර්ථකව වෙනස් කරන ලදි!");
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
    })
    .catch(err => {
      console.error(err);
      alert("❌ රහස්පදය වෙනස් කිරීමට නොහැකි විය. කරුණාකර වත්මන් රහස්පදය නිවැරදිදැයි පරීක්ෂා කරන්න.");
    });
  };

  // 🟢 DYNAMIC UTILITY: යූටියුබ් හෝ සාමාන්‍ය ලින්ක් එකක්ද කියා පරිවර්තනය කරන ෆන්ක්ෂන් එක
  const getMediaViewerComponent = (material) => {
    const path = material.file_path || '';
    
    if (path.includes('youtube.com') || path.includes('youtu.be')) {
      let videoId = '';
      if (path.includes('youtu.be/')) {
        videoId = path.split('youtu.be/')[1]?.split(/[?#]/)[0];
      } else if (path.includes('v=')) {
        videoId = path.split('v=')[1]?.split(/[&#]/)[0];
      } else if (path.includes('embed/')) {
        videoId = path.split('embed/')[1]?.split(/[?#]/)[0];
      }
      
      const embedUrl = `https://www.youtube.com/embed/${videoId}`;
      return (
        <iframe 
          src={embedUrl} 
          title={material.title} 
          style={{ width: '100%', height: '440px', border: 'none', borderRadius: '8px' }} 
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
          allowFullScreen
        />
      );
    }

    if (path.toLowerCase().endsWith('.mp4') || (material.material_type && material.material_type.toLowerCase().includes('video'))) {
      return (
        <video src={`http://localhost:8082/${path}`} controls controlsList="nodownload" autoPlay style={{ width: '100%', maxHeight: '440px', borderRadius: '8px' }} />
      );
    }

    return (
      <iframe src={`http://localhost:8082/${path}#toolbar=0`} title={material.title} style={{ width: '100%', height: '490px', border: 'none', borderRadius: '8px', backgroundColor: 'white' }} />
    );
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      
      {/* LEFT SIDEBAR UI */}
      <div style={styles.sidebar}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
          <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT PORTAL</p>
        </div>
        
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <button onClick={() => { setActiveTab('dashboard'); setSelectedSubjectFilter(''); }} style={styles.sidebarBtn(activeTab === 'dashboard')}>🏠 Dashboard Overview</button>
          <button onClick={() => setActiveTab('materials')} style={styles.sidebarBtn(activeTab === 'materials')}>📚 My Learning Materials ({displayedMaterials.length})</button>
          <button onClick={() => setActiveTab('exams')} style={styles.sidebarBtn(activeTab === 'exams')}>📝 My Online Exams ({displayedQuizzes.length})</button>
          <button onClick={() => setActiveTab('forum')} style={styles.sidebarBtn(activeTab === 'forum')}>💬 Class Forum Space</button>
          <button onClick={() => setActiveTab('profile')} style={styles.sidebarBtn(activeTab === 'profile')}>👤 Profile Identity</button>
        </div>

        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
          <button onClick={handleLogout} style={styles.logoutBtn}>🚪 Logout Portal</button>
        </div>
      </div>

      {/* MAIN WORKSPACE CORE AREA */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        
        {/* TAB 1: DASHBOARD OVERVIEW */}
        {activeTab === 'dashboard' && (
          <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '25px' }}>
            <div style={styles.welcomeBanner}>
              <h1 style={{ margin: '0 0 8px 0', fontSize: '26px' }}>Welcome back, {displayNameStr}! 🎓</h1>
              <p style={{ margin: 0, opacity: 0.9, fontSize: '14px' }}>Access your online classrooms, download handouts, and join live quizzes instantly.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '20px' }}>
              <div style={styles.statCard('#7c3aed')}>
                <div><p style={styles.statLabel}>My Registered Grade</p><h2 style={styles.statValue}>{displayGradeStr}</h2></div>
                <div style={styles.statIcon}>🏫</div>
              </div>
              <div style={styles.statCard('#2563eb')}>
                <div><p style={styles.statLabel}>Total Handouts</p><h2 style={styles.statValue}>{materials.length} Materials</h2></div>
                <div style={styles.statIcon}>📂</div>
              </div>
              <div style={styles.statCard('#ea580c')}>
                <div><p style={styles.statLabel}>Live Active Quizzes</p><h2 style={styles.statValue}>{quizzes.length} Papers</h2></div>
                <div style={styles.statIcon}>✏️</div>
              </div>
            </div>

            <h3 style={{ color: '#1e293b', margin: '15px 0 0 0', fontSize: '18px' }}>
              🏫 My Classrooms ({displayGradeStr} / Enrolled Subjects)
            </h3>
            <p style={{ color: '#64748b', fontSize: '12.5px', marginTop: '-15px' }}>💡 Quick Action: Click any subject matrix card below to filter materials specifically for that stream.</p>

            {/* MAPPED CLASSROOMS MATRIX */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '20px' }}>
              {mySubjects.map((sub, idx) => (
                <div 
                  key={idx} 
                  onClick={() => { setSelectedSubjectFilter(sub); setActiveTab('materials'); }}
                  style={styles.classCard}
                  onMouseOver={e => e.currentTarget.style.transform='translateY(-4px)'} 
                  onMouseOut={e => e.currentTarget.style.transform='translateY(0)'}
                >
                  <div style={{ fontWeight: 'bold', color: '#1e293b', fontSize: '15px' }}>{displayGradeStr} - {sub}</div>
                  <div style={{ fontSize: '12px', color: '#16a34a', marginTop: '8px', fontWeight: 'bold', backgroundColor: '#dcfce7', display: 'inline-block', padding: '3px 8px', borderRadius: '4px' }}>
                    🎯 Click to Open Center
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* TAB 2: MY LEARNING MATERIALS */}
        {activeTab === 'materials' && (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <div>
                <h3 style={{ color: '#1e293b', fontSize: '20px', margin: 0 }}>
                  📚 Enrolled Materials Archive {selectedSubjectFilter ? `(${selectedSubjectFilter} විෂය සඳහා පමණි)` : ''}
                </h3>
                <p style={{ color: '#64748b', fontSize: '13px', margin: '4px 0 0 0' }}>ගුරුවරුන් විසින් අප්ලෝඩ් කරන ලද සියලුම ලිපිගොනු සහ වීඩියෝ දර්ශන.</p>
              </div>
              
              <div style={{ display: 'flex', gap: '8px' }}>
                <button onClick={() => setSelectedSubjectFilter('')} style={styles.filterToggleBtn(!selectedSubjectFilter)}>All Subjects ({materials.length})</button>
                {mySubjects.map(sub => (
                  <button key={sub} onClick={() => setSelectedSubjectFilter(sub)} style={styles.filterToggleBtn(selectedSubjectFilter === sub)}>{sub}</button>
                ))}
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {displayedMaterials.map((m, i) => (
                <div key={i} style={{ backgroundColor: 'white', padding: '16px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 2px 8px rgba(0,0,0,0.01)' }}>
                  <div>
                    <h5 style={{ margin: 0, fontSize: '14.5px', color: '#1e293b', fontWeight: '600' }}>{m.title}</h5>
                    <span style={{ fontSize: '11.5px', color: '#2563eb', fontWeight: 'bold', backgroundColor: '#dbeafe', padding: '2px 8px', borderRadius: '4px', marginTop: '5px', display: 'inline-block' }}>
                      {m.subject} {m.material_type ? `| ${m.material_type}` : ''}
                    </span>
                  </div>
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <button onClick={() => setPreviewMaterial(m)} style={{ backgroundColor: '#16a34a', color: 'white', padding: '8px 15px', borderRadius: '8px', border: 'none', fontSize: '12.5px', fontWeight: 'bold', cursor: 'pointer' }}>👁️ View In-App</button>
                    <a href={m.file_path && (m.file_path.includes('http') ? m.file_path : `http://localhost:8082/${m.file_path}`)} target="_blank" rel="noreferrer" style={{ backgroundColor: '#2563eb', color: 'white', padding: '8px 15px', borderRadius: '8px', textDecoration: 'none', fontSize: '12.5px', fontWeight: 'bold' }}>📥 Download</a>
                  </div>
                </div>
              ))}
              {displayedMaterials.length === 0 && <p style={{ color: '#94a3b8', fontStyle: 'italic', textAlign: 'center', padding: '30px' }}>📭 මෙම විෂයට අදාළ නිබන්ධන කිසිවක් දැනට සොයාගත නොහැක.</p>}
            </div>
          </div>
        )}

        {/* TAB 3: ONLINE EXAMS MODULE */}
        {activeTab === 'exams' && (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px' }}>
              <div>
                <h3 style={{ color: '#1e293b', fontSize: '20px', margin: 0 }}>📝 Active Examination Blueprint {selectedSubjectFilter ? `(${selectedSubjectFilter})` : ''}</h3>
                <p style={{ color: '#64748b', fontSize: '13px', margin: '4px 0 0 0' }}>ඔබගේ විෂය මාලාවට අදාළව දැනට පවත්වනු ලබන සක්‍රීය බහුවරණ (MCQ) ප්‍රශ්න පත්‍ර.</p>
              </div>
              <div style={{ display: 'flex', gap: '8px' }}>
                <button onClick={() => setSelectedSubjectFilter('')} style={styles.filterToggleBtn(!selectedSubjectFilter)}>All Exams ({quizzes.length})</button>
                {mySubjects.map(sub => (
                  <button key={sub} onClick={() => setSelectedSubjectFilter(sub)} style={styles.filterToggleBtn(selectedSubjectFilter === sub)}>{sub}</button>
                ))}
              </div>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {displayedQuizzes.map((q, i) => (
                <div key={i} style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderLeft: '5px solid #ea580c', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 4px 10px rgba(0,0,0,0.01)' }}>
                  <div>
                    <h4 style={{ margin: '0 0 5px 0', fontSize: '15px', color: '#1e293b' }}>{q.title}</h4>
                    <div style={{ display: 'flex', gap: '8px', fontSize: '11px', fontWeight: 'bold' }}>
                      <span style={{ color: '#ea580c', backgroundColor: '#fff7ed', padding: '2px 6px', borderRadius: '4px' }}>{q.subject_name}</span>
                      <span style={{ color: '#16a34a', backgroundColor: '#dcfce7', padding: '2px 6px', borderRadius: '4px' }}>Status: Live</span>
                    </div>
                  </div>
                  <button onClick={() => alert(`🚀 "${q.title}" ප්‍රශ්න පත්‍රයට පිළිතුරු සැපයීමේ පද්ධතිය සාර්ථකව සම්බන්ධ වෙමින් පවතී!`)} style={{ backgroundColor: '#ea580c', color: 'white', border: 'none', padding: '10px 18px', borderRadius: '8px', fontSize: '13px', fontWeight: 'bold', cursor: 'pointer' }}>🚀 Start Assessment</button>
                </div>
              ))}
              {displayedQuizzes.length === 0 && <p style={{ color: '#94a3b8', fontStyle: 'italic', textAlign: 'center', padding: '30px' }}>📭 මෙම විෂයට අදාළ සක්‍රීය විභාග කිසිවක් නැත.</p>}
            </div>
          </div>
        )}

        {/* TAB 4: CLASS FORUM SPACE */}
        {activeTab === 'forum' && (
          <div style={{ animation: 'fadeIn 0.5s', backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
            <h3 style={{ margin: '0 0 5px 0', color: '#1e293b' }}>💬 Student & Teacher Chat Forum</h3>
            <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 20px 0' }}>ගුරුවරුන් සහ සිසුන් අතර විෂය කරුණු ගැටළු සාකච්ඡා කිරීමට වෙන්වූ පොදු පුවරුව.</p>
            <div style={{ border: '1px solid #cbd5e1', borderRadius: '10px', height: '220px', backgroundColor: '#f8fafc', padding: '15px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '10px' }}>
              <div style={{ alignSelf: 'flex-start', backgroundColor: '#e2e8f0', padding: '10px 14px', borderRadius: '10px', maxWidth: '70%', fontSize: '13px' }}>
                <strong style={{ display: 'block', fontSize: '11px', color: '#475569' }}>Buddhika Darshani (Teacher)</strong>
                ළමයි, Lesson 01 එකේ ගණිත ගැටළු වල මොනවා හරි නොවැටහෙන තැන් තියෙනවද?
              </div>
              <div style={{ alignSelf: 'flex-end', backgroundColor: '#dcfce7', padding: '10px 14px', borderRadius: '10px', maxWidth: '70%', fontSize: '13px' }}>
                <strong style={{ display: 'block', fontSize: '11px', color: '#16a34a' }}>Me ({displayNameStr})</strong>
                නැහැ ටීචර්, වීඩියෝ එක බැලුවට පස්සේ ඔක්කොම ලස්සනට තේරුණා. 
              </div>
            </div>
            <div style={{ display: 'flex', gap: '10px', marginTop: '15px' }}>
              <input type="text" placeholder="Type your subject question here..." style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13.5px', outline: 'none' }} />
              <button onClick={() => alert("💬 පණිවිඩය සාර්ථකව සාකච්ඡා මණ්ඩපයට එක් කරන ලදි!")} style={{ backgroundColor: '#145c2e', color: 'white', border: 'none', padding: '0 20px', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Send 🚀</button>
            </div>
          </div>
        )}

        {/* TAB 5: PROFILE IDENTITY */}
        {activeTab === 'profile' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '25px', maxWidth: '500px', animation: 'fadeIn 0.5s' }}>
            
            {/* Student Credentials Card */}
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
              <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>👤 My Profile Credentials</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', fontSize: '14px' }}>
                <div><strong style={{ color: '#64748b', display: 'block', fontSize: '11px' }}>FULL NAME</strong><span style={{ fontWeight: 'bold', color: '#1e293b' }}>{displayNameStr}</span></div>
                <div><strong style={{ color: '#64748b', display: 'block', fontSize: '11px' }}>REGISTERED GRADE</strong><span>{displayGradeStr}</span></div>
                <div><strong style={{ color: '#64748b', display: 'block', fontSize: '11px' }}>ENROLLED SUBJECTS</strong><span style={{ color: '#2563eb', fontWeight: 'bold' }}>{displaySubjectsStr || 'None'}</span></div>
              </div>
            </div>

            {/* 🔒 Security & Password Update Card */}
            <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
              <h3 style={{ margin: '0 0 5px 0', color: '#1e293b' }}>🔒 Account Security</h3>
              <p style={{ color: '#64748b', fontSize: '12.5px', margin: '0 0 20px 0' }}>Update your portal access credentials below.</p>
              
              <form onSubmit={handlePasswordChange} style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
                <div>
                  <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', color: '#475569', marginBottom: '5px' }}>CURRENT PASSWORD</label>
                  <input 
                    type="password" 
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    placeholder="••••••••" 
                    style={styles.formInput} 
                  />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', color: '#475569', marginBottom: '5px' }}>NEW PASSWORD</label>
                  <input 
                    type="password" 
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="••••••••" 
                    style={styles.formInput} 
                  />
                </div>
                <div>
                  <label style={{ display: 'block', fontSize: '11px', fontWeight: 'bold', color: '#475569', marginBottom: '5px' }}>CONFIRM NEW PASSWORD</label>
                  <input 
                    type="password" 
                    value={confirmPassword}
                    onChange={(e) => setConfirmPassword(e.target.value)}
                    placeholder="••••••••" 
                    style={styles.formInput} 
                  />
                </div>
                <button type="submit" style={styles.savePasswordBtn}>
                  💾 Save New Password
                </button>
              </form>
            </div>

          </div>
        )}

      </div>

      {/* DYNAMIC LESSON INTERACTIVE PREVIEW MODAL */}
      {previewMaterial && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px', borderBottom: '2px solid #e2e8f0', paddingBottom: '12px' }}>
              <div>
                <h4 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: 'bold' }}>📖 Smart Lesson View: {previewMaterial.title}</h4>
                <span style={{ fontSize: '11px', color: '#64748b', fontWeight: '500' }}>Target Mapped Node: {previewMaterial.subject} | {previewMaterial.grade}</span>
              </div>
              <button onClick={() => setPreviewMaterial(null)} style={{ background: '#fee2e2', border: 'none', fontSize: '14px', cursor: 'pointer', color: '#b91c1c', padding: '5px 10px', borderRadius: '6px', fontWeight: 'bold' }}>✕ Close Viewer</button>
            </div>
            <div style={{ backgroundColor: '#f1f5f9', padding: '8px', borderRadius: '10px', display: 'center', justifyContent: 'center', alignItems: 'center' }}>
              {getMediaViewerComponent(previewMaterial)}
            </div>
          </div>
        </div>
      )}

    </div>
  );
}

const styles = {
  sidebar: { width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 },
  sidebarBtn: (active) => ({ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }),
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px' },
  welcomeBanner: { backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white' },
  statCard: (color) => ({ backgroundColor: 'white', padding: '22px', borderRadius: '15px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderLeft: `5px solid ${color}`, boxShadow: '0 4px 15px rgba(0,0,0,0.01)', border: '1px solid #e2e8f0' }),
  statLabel: { margin: 0, color: '#64748b', fontSize: '12.5px', fontWeight: 'bold' },
  statValue: { fontSize: '18px', marginTop: '5px', marginBottom: 0, color: '#1e293b', fontWeight: '700' },
  statIcon: { fontSize: '24px', opacity: 0.7 },
  classCard: { backgroundColor: 'white', padding: '20px', borderRadius: '12px', borderTop: '5px solid #145c2e', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', borderLeft: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0', cursor: 'pointer', transition: '0.2s' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(15, 23, 42, 0.6)', backdropFilter: 'blur(4px)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 2000 },
  modal: { backgroundColor: 'white', padding: '25px', borderRadius: '16px', width: '780px', maxWidth: '90%', boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)', border: '1px solid #cbd5e1' },
  
  filterToggleBtn: (isActive) => ({
    padding: '6px 14px',
    backgroundColor: isActive ? '#145c2e' : 'white',
    color: isActive ? 'white' : '#475569',
    border: isActive ? '1px solid #145c2e' : '1px solid #cbd5e1',
    borderRadius: '6px',
    fontSize: '12px',
    fontWeight: 'bold',
    cursor: 'pointer',
    transition: '0.2s'
  }),

  // 🟢 NEW FORM INPUT STYLES
  formInput: {
    width: '100%',
    padding: '10px 12px',
    borderRadius: '8px',
    border: '1px solid #cbd5e1',
    fontSize: '13.5px',
    outline: 'none',
    boxSizing: 'border-box',
    marginTop: '2px',
    backgroundColor: '#f8fafc',
    transition: '0.2s focus',
  },
  savePasswordBtn: {
    backgroundColor: '#145c2e',
    color: 'white',
    border: 'none',
    padding: '12px',
    borderRadius: '8px',
    fontWeight: 'bold',
    cursor: 'pointer',
    fontSize: '13.5px',
    marginTop: '5px',
    transition: 'background-color 0.2s'
  }
};
